from datetime import datetime,timezone
from . import db
def now(): return datetime.now(timezone.utc)
class User(db.Model):
 id=db.Column(db.Integer,primary_key=True);name=db.Column(db.String(120),nullable=False);email=db.Column(db.String(254),unique=True,index=True,nullable=False);phone=db.Column(db.String(40),default='');role=db.Column(db.String(20),default='customer',nullable=False);password_hash=db.Column(db.String(255),nullable=False);active=db.Column(db.Boolean,default=True,nullable=False);email_verified=db.Column(db.Boolean,default=False,nullable=False);must_change_password=db.Column(db.Boolean,default=False,nullable=False);created_at=db.Column(db.DateTime(timezone=True),default=now)
class Service(db.Model):
 id=db.Column(db.Integer,primary_key=True);name=db.Column(db.String(120),nullable=False);slug=db.Column(db.String(140),unique=True,nullable=False);description=db.Column(db.Text,default='');image_url=db.Column(db.String(500),default='');starting_price_minor=db.Column(db.Integer);currency=db.Column(db.String(3),default='ZMW');active=db.Column(db.Boolean,default=True);sort_order=db.Column(db.Integer,default=0)
class Booking(db.Model):
 id=db.Column(db.Integer,primary_key=True);reference=db.Column(db.String(24),unique=True,index=True,nullable=False);customer_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False,index=True);service_id=db.Column(db.Integer,db.ForeignKey('service.id'),nullable=False);vehicle_description=db.Column(db.String(200),nullable=False);preferred_at=db.Column(db.DateTime(timezone=True),nullable=False);scheduled_at=db.Column(db.DateTime(timezone=True));assigned_detailer_id=db.Column(db.Integer,db.ForeignKey('user.id'));status=db.Column(db.String(30),default='requested',nullable=False);customer_notes=db.Column(db.Text,default='');staff_notes=db.Column(db.Text,default='');created_at=db.Column(db.DateTime(timezone=True),default=now)
class QuoteRequest(db.Model):
 id=db.Column(db.Integer,primary_key=True);name=db.Column(db.String(120),nullable=False);email=db.Column(db.String(254),nullable=False);phone=db.Column(db.String(40),nullable=False);details=db.Column(db.Text,nullable=False);status=db.Column(db.String(24),default='new');created_at=db.Column(db.DateTime(timezone=True),default=now)
class Quotation(db.Model):
 id=db.Column(db.Integer,primary_key=True);reference=db.Column(db.String(24),unique=True,nullable=False);customer_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False);booking_id=db.Column(db.Integer,db.ForeignKey('booking.id'));status=db.Column(db.String(24),default='draft');currency=db.Column(db.String(3),default='ZMW');subtotal_minor=db.Column(db.Integer,default=0);tax_minor=db.Column(db.Integer,default=0);total_minor=db.Column(db.Integer,default=0);valid_until=db.Column(db.Date);notes=db.Column(db.Text,default='');created_at=db.Column(db.DateTime(timezone=True),default=now)
class Invoice(db.Model):
 id=db.Column(db.Integer,primary_key=True);reference=db.Column(db.String(24),unique=True,nullable=False);customer_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False);booking_id=db.Column(db.Integer,db.ForeignKey('booking.id'));quotation_id=db.Column(db.Integer,db.ForeignKey('quotation.id'));status=db.Column(db.String(24),default='issued');currency=db.Column(db.String(3),default='ZMW');subtotal_minor=db.Column(db.Integer,default=0);tax_minor=db.Column(db.Integer,default=0);total_minor=db.Column(db.Integer,default=0);amount_paid_minor=db.Column(db.Integer,default=0);due_date=db.Column(db.Date);created_at=db.Column(db.DateTime(timezone=True),default=now)
class Payment(db.Model):
 id=db.Column(db.Integer,primary_key=True);invoice_id=db.Column(db.Integer,db.ForeignKey('invoice.id'),nullable=False);amount_minor=db.Column(db.Integer,nullable=False);method=db.Column(db.String(30),nullable=False);reference=db.Column(db.String(100),default='');recorded_by=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False);paid_at=db.Column(db.DateTime(timezone=True),default=now)
class PayrollRun(db.Model):
 id=db.Column(db.Integer,primary_key=True);period_start=db.Column(db.Date,nullable=False);period_end=db.Column(db.Date,nullable=False);status=db.Column(db.String(20),default='draft');created_by=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False);created_at=db.Column(db.DateTime(timezone=True),default=now)
class Payslip(db.Model):
 id=db.Column(db.Integer,primary_key=True);payroll_run_id=db.Column(db.Integer,db.ForeignKey('payroll_run.id'),nullable=False);employee_id=db.Column(db.Integer,db.ForeignKey('user.id'),nullable=False);gross_minor=db.Column(db.Integer,default=0);deductions_minor=db.Column(db.Integer,default=0);net_minor=db.Column(db.Integer,default=0);currency=db.Column(db.String(3),default='ZMW');statement_json=db.Column(db.JSON,default=dict)
